files.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  padding: 16px;
}

.card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 12px;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  color: #e94560;
  font-size: 1.5rem;
  margin-bottom: 24px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.bpm-section {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
}

.bpm-display {
  color: #eaeaea;
  font-size: 3rem;
  font-weight: 700;
  min-width: 120px;
  font-variant-numeric: tabular-nums;
}

.btn {
  background: #0f3460;
  color: #eaeaea;
  border: 3px solid #e94560;
  border-radius: 8px;
  padding: 12px 20px;
  font-size: 1.5rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  min-width: 56px;
  min-height: 56px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn:hover {
  background: #1a4a7a;
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

.btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 3px;
}

.btn:active {
  background: #e94560;
  color: #16213e;
  transform: scale(0.95);
}

.controls {
  margin-bottom: 24px;
}

.start-stop {
  width: 100%;
  font-size: 1.25rem;
  padding: 16px;
  border-color: #e94560;
}

.start-stop.running {
  background: #e94560;
  color: #16213e;
}

.start-stop.running:hover {
  background: #f05a75;
}

.beat-section {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
}

.beat-light {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #0f3460;
  border: 3px solid #e94560;
  transition: background 0.05s, box-shadow 0.05s;
}

.beat-light.flash {
  background: #e94560;
  box-shadow: 0 0 20px #e94560, 0 0 40px rgba(233, 69, 96, 0.5);
}

.beat-counter {
  display: flex;
  flex-direction: column;
  align-items: center;
  color: #a0a0b0;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.beat-count {
  color: #eaeaea;
  font-size: 2rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .bpm-display {
    font-size: 2.5rem;
    min-width: 90px;
  }
  .btn {
    font-size: 1.25rem;
    padding: 10px 16px;
    min-width: 48px;
    min-height: 48px;
  }
  .beat-light {
    width: 40px;
    height: 40px;
  }
}

(function () {
  'use strict';

  const MIN_BPM = 40;
  const MAX_BPM = 200;
  const FLASH_DURATION = 80;

  let bpm = 120;
  let running = false;
  let beatCount = 0;
  let timerId = null;
  let flashTimeoutId = null;
  let nextTickTime = 0;

  const bpmDisplay = document.getElementById('bpm-display');
  const bpmMinus = document.getElementById('bpm-minus');
  const bpmPlus = document.getElementById('bpm-plus');
  const startStopBtn = document.getElementById('start-stop');
  const beatLight = document.getElementById('beat-light');
  const beatCountEl = document.getElementById('beat-count');

  function updateBpmDisplay() {
    bpmDisplay.textContent = bpm;
  }

  function setBpm(value) {
    bpm = Math.min(MAX_BPM, Math.max(MIN_BPM, value));
    updateBpmDisplay();
    if (running) {
      restartTimer();
    }
  }

  function flashLight() {
    beatLight.classList.add('flash');
    if (flashTimeoutId) clearTimeout(flashTimeoutId);
    flashTimeoutId = setTimeout(function () {
      beatLight.classList.remove('flash');
      flashTimeoutId = null;
    }, FLASH_DURATION);
  }

  function tick() {
    beatCount++;
    beatCountEl.textContent = beatCount;
    flashLight();
    scheduleNextTick();
  }

  function scheduleNextTick() {
    const interval = 60000 / bpm;
    nextTickTime += interval;
    const delay = Math.max(0, nextTickTime - performance.now());
    timerId = setTimeout(tick, delay);
  }

  function start() {
    if (running) return;
    running = true;
    beatCount = 0;
    beatCountEl.textContent = '0';
    startStopBtn.textContent = 'Stop';
    startStopBtn.setAttribute('aria-label', 'Stop metronome');
    startStopBtn.classList.add('running');
    nextTickTime = performance.now();
    tick();
  }

  function stop() {
    if (!running) return;
    running = false;
    if (timerId) {
      clearTimeout(timerId);
      timerId = null;
    }
    if (flashTimeoutId) {
      clearTimeout(flashTimeoutId);
      flashTimeoutId = null;
    }
    beatLight.classList.remove('flash');
    startStopBtn.textContent = 'Start';
    startStopBtn.setAttribute('aria-label', 'Start metronome');
    startStopBtn.classList.remove('running');
  }

  function restartTimer() {
    if (timerId) {
      clearTimeout(timerId);
      timerId = null;
    }
    nextTickTime = performance.now();
    scheduleNextTick();
  }

  bpmMinus.addEventListener('click', function () {
    setBpm(bpm - 1);
  });

  bpmPlus.addEventListener('click', function () {
    setBpm(bpm + 1);
  });

  startStopBtn.addEventListener('click', function () {
    if (running) {
      stop();
    } else {
      start();
    }
  });

  updateBpmDisplay();
})();
